import { roomsDummyData } from "@/assets/assets";
import Image from "next/image";

const Page = () => {
  return (
    <div className="flex flex-col-reverse lg:flex-row items-center justify-center pt-28 md:pt-35 px-4 md:px-16 lg:px-24">
      {/* Rooms */}
      <div>
        <div className="flex flex-col items-center text-left">
          <h1 className="front-playfair text-4xl md:text-[40px]">Hotel Rooms</h1>
          <p className="text-sm md:text-base text-gray-500/90 mt-2">Take advantage of our limited-time offers and special packages to enhance your stay and create unforgettable memories.</p>
        </div>

        {roomsDummyData.map((room) => (
          <div key={room._id}>
            <Image src={room.images[0]} width={100} height={100} className="max-h-65 md:w-1/2 rounded-xl shadow-lg object-cover cursor-pointer" alt="" />
          </div>
        ))}

      </div>
      {/* Filters */}
      <div></div>
    </div>
  );
}

export default Page;
